/*
===============================================================
HE THONG GIAM SAT THI CHONG THI HO - SQL SERVER
===============================================================
Muc dich: Database khoi tao dau tien cho prototype nghien cuu
Client - Server trong phong thi.

PHAM VI DU LIEU:
- 84 sinh vien + Face Embedding 512 chieu.
- 3 phong thi, toi da 30 may/phong.
- 3 ca thi, moi ca 60 phut.
- 1 ky thi minh hoa.
- 2 vai tro: SINH_VIEN va GIAM_THI.
- Phan bo thi: P101-Ca 1 (30 SV), P102-Ca 1 (30 SV), P103-Ca 2 (24 SV).
- MaSinhVien = SV001..SV084 la ma noi bo de lien ket duy nhat.
- MSSV = ma sinh vien goc tu file student_info.csv.
- FaceEmbedding = JSON array gom 512 gia tri tu face_db_export.xlsx.

LUU Y:
- Day la script cho LAN TAO DATABASE DAU TIEN.
- KHONG co DROP DATABASE / DROP TABLE.
- Chay TOAN BO file mot lan trong SQL Server Management Studio.
===============================================================
*/
CREATE DATABASE HeThongGiamSatThi;
GO
USE HeThongGiamSatThi;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRY
    BEGIN TRANSACTION;

-- ============================================================
-- 1. TAI KHOAN
-- ============================================================
CREATE TABLE TaiKhoan (
    MaTaiKhoan INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_TaiKhoan PRIMARY KEY,
    TenDangNhap NVARCHAR(50) NOT NULL CONSTRAINT UQ_TaiKhoan_TenDangNhap UNIQUE,
    MatKhau NVARCHAR(255) NOT NULL,
    VaiTro NVARCHAR(20) NOT NULL,
    DangHoatDong BIT NOT NULL CONSTRAINT DF_TaiKhoan_DangHoatDong DEFAULT (1),
    NgayTao DATETIME2(0) NOT NULL CONSTRAINT DF_TaiKhoan_NgayTao DEFAULT SYSDATETIME(),
    CONSTRAINT CK_TaiKhoan_VaiTro CHECK (VaiTro IN (N'SINH_VIEN', N'GIAM_THI'))
);

-- ============================================================
-- 2. SINH VIEN
-- ============================================================
CREATE TABLE SinhVien (
    MaSinhVien NVARCHAR(10) NOT NULL CONSTRAINT PK_SinhVien PRIMARY KEY,
    STT INT NOT NULL CONSTRAINT UQ_SinhVien_STT UNIQUE,
    MSSV NVARCHAR(30) NOT NULL,
    HoTen NVARCHAR(150) NOT NULL,
    MaTaiKhoan INT NOT NULL CONSTRAINT UQ_SinhVien_MaTaiKhoan UNIQUE,
    FaceEmbedding NVARCHAR(MAX) NOT NULL,
    NgayTao DATETIME2(0) NOT NULL CONSTRAINT DF_SinhVien_NgayTao DEFAULT SYSDATETIME(),
    CONSTRAINT FK_SinhVien_TaiKhoan FOREIGN KEY (MaTaiKhoan) REFERENCES TaiKhoan(MaTaiKhoan),
    CONSTRAINT CK_SinhVien_MaSinhVien CHECK (MaSinhVien LIKE N'SV[0-9][0-9][0-9]'),
    CONSTRAINT CK_SinhVien_Embedding_JSON CHECK (ISJSON(FaceEmbedding) = 1)
);

-- ============================================================
-- 3. PHONG THI
-- ============================================================
CREATE TABLE PhongThi (
    MaPhong INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_PhongThi PRIMARY KEY,
    TenPhong NVARCHAR(20) NOT NULL CONSTRAINT UQ_PhongThi_TenPhong UNIQUE,
    SucChua INT NOT NULL CONSTRAINT DF_PhongThi_SucChua DEFAULT (30),
    MoTa NVARCHAR(200) NULL,
    CONSTRAINT CK_PhongThi_SucChua CHECK (SucChua BETWEEN 1 AND 30)
);

-- ============================================================
-- 4. CA THI - moi ca 60 phut
-- ============================================================
CREATE TABLE CaThi (
    MaCa INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_CaThi PRIMARY KEY,
    TenCa NVARCHAR(50) NOT NULL CONSTRAINT UQ_CaThi_TenCa UNIQUE,
    GioBatDau TIME(0) NOT NULL,
    GioKetThuc TIME(0) NOT NULL,
    ThoiLuongPhut AS DATEDIFF(MINUTE, GioBatDau, GioKetThuc) PERSISTED,
    CONSTRAINT CK_CaThi_60Phut CHECK (DATEDIFF(MINUTE, GioBatDau, GioKetThuc) = 60)
);

-- ============================================================
-- 5. KY THI
-- ============================================================
CREATE TABLE KyThi (
    MaKyThi INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_KyThi PRIMARY KEY,
    MaKyThiCode NVARCHAR(30) NOT NULL CONSTRAINT UQ_KyThi_Code UNIQUE,
    TenKyThi NVARCHAR(200) NOT NULL,
    NgayThi DATE NOT NULL,
    TrangThai NVARCHAR(30) NOT NULL CONSTRAINT DF_KyThi_TrangThai DEFAULT N'Chua dien ra',
    NguongNhanDien DECIMAL(6,4) NOT NULL CONSTRAINT DF_KyThi_Nguong DEFAULT (0.6000),
    ThoiGianKhongCoMatGiay INT NOT NULL CONSTRAINT DF_KyThi_NoFace DEFAULT (3),
    SoLanSaiLienTiep INT NOT NULL CONSTRAINT DF_KyThi_Mismatch DEFAULT (3),
    ThoiGianNhieuKhuonMatGiay INT NOT NULL CONSTRAINT DF_KyThi_Multi DEFAULT (2),
    CONSTRAINT CK_KyThi_TrangThai CHECK (TrangThai IN (N'Chua dien ra',N'Dang dien ra',N'Da ket thuc')),
    CONSTRAINT CK_KyThi_Nguong CHECK (NguongNhanDien > 0 AND NguongNhanDien <= 1),
    CONSTRAINT CK_KyThi_ThamSo CHECK (ThoiGianKhongCoMatGiay > 0 AND SoLanSaiLienTiep > 0 AND ThoiGianNhieuKhuonMatGiay > 0)
);

-- ============================================================
-- 6. MAY TRAM - 30 PC / PHONG
-- ============================================================
CREATE TABLE MayTram (
    MaMay INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_MayTram PRIMARY KEY,
    MaPhong INT NOT NULL,
    MaPC NVARCHAR(20) NOT NULL,
    TenMay NVARCHAR(100) NOT NULL,
    DiaChiIP VARCHAR(45) NULL,
    TrangThai NVARCHAR(20) NOT NULL CONSTRAINT DF_MayTram_TrangThai DEFAULT N'Ngoai tuyen',
        CONSTRAINT CK_MayTram_TrangThai CHECK (TrangThai IN (N'Online',N'Ngoai tuyen')),
    LanCuoiKetNoi DATETIME2(0) NULL,
    CONSTRAINT FK_MayTram_Phong FOREIGN KEY (MaPhong) REFERENCES PhongThi(MaPhong),
    CONSTRAINT UQ_MayTram_Phong_PC UNIQUE (MaPhong, MaPC)
);

-- ============================================================
-- 7. PHIEN THI
-- ============================================================
CREATE TABLE PhienThi (
    MaPhienThi INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_PhienThi PRIMARY KEY,
    MaKyThi INT NOT NULL,
    MaPhong INT NOT NULL,
    MaCa INT NOT NULL,
    TrangThai NVARCHAR(30) NOT NULL CONSTRAINT DF_PhienThi_TrangThai DEFAULT N'Chua bat dau',
        CONSTRAINT CK_PhienThi_TrangThai CHECK (TrangThai IN (N'Chua bat dau',N'Dang thi',N'Da ket thuc')),
    CONSTRAINT FK_PhienThi_KyThi FOREIGN KEY (MaKyThi) REFERENCES KyThi(MaKyThi),
    CONSTRAINT FK_PhienThi_Phong FOREIGN KEY (MaPhong) REFERENCES PhongThi(MaPhong),
    CONSTRAINT FK_PhienThi_Ca FOREIGN KEY (MaCa) REFERENCES CaThi(MaCa),
    CONSTRAINT UQ_PhienThi UNIQUE (MaKyThi, MaPhong, MaCa)
);

-- ============================================================
-- 8. THI SINH TRONG PHIEN
-- ============================================================
CREATE TABLE ThiSinhTrongPhien (
    MaThamGia INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_ThiSinhTrongPhien PRIMARY KEY,
    MaPhienThi INT NOT NULL,
    MaSinhVien NVARCHAR(10) NOT NULL,
    MaMay INT NULL,
    ThoiGianDangNhap DATETIME2(0) NULL,
    ThoiGianDangXuat DATETIME2(0) NULL,
    TrangThai NVARCHAR(30) NOT NULL CONSTRAINT DF_ThiSinh_TrangThai DEFAULT N'Chua dang nhap',
        CONSTRAINT CK_ThiSinh_TrangThai CHECK (TrangThai IN (N'Chua dang nhap',N'Dang thi',N'Da nop',N'Da ket thuc',N'Da dang xuat',N'Ngoai tuyen')),
    CONSTRAINT FK_ThiSinh_Phien FOREIGN KEY (MaPhienThi) REFERENCES PhienThi(MaPhienThi),
    CONSTRAINT FK_ThiSinh_SinhVien FOREIGN KEY (MaSinhVien) REFERENCES SinhVien(MaSinhVien),
    CONSTRAINT FK_ThiSinh_May FOREIGN KEY (MaMay) REFERENCES MayTram(MaMay),
    CONSTRAINT UQ_ThiSinh_Phien_SV UNIQUE (MaPhienThi, MaSinhVien)
);

-- ============================================================
-- 9. CAU HOI BAI THI MINH HOA
-- ============================================================
CREATE TABLE CauHoi (
    MaCauHoi INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_CauHoi PRIMARY KEY,
    MaKyThi INT NOT NULL,
    SoThuTu INT NOT NULL,
    NoiDung NVARCHAR(1000) NOT NULL,
    LuaChonA NVARCHAR(500) NOT NULL,
    LuaChonB NVARCHAR(500) NOT NULL,
    LuaChonC NVARCHAR(500) NOT NULL,
    LuaChonD NVARCHAR(500) NOT NULL,
    DapAnDung CHAR(1) NOT NULL,
    CONSTRAINT FK_CauHoi_KyThi FOREIGN KEY (MaKyThi) REFERENCES KyThi(MaKyThi),
    CONSTRAINT UQ_CauHoi_KyThi_STT UNIQUE (MaKyThi, SoThuTu),
    CONSTRAINT CK_CauHoi_DapAn CHECK (DapAnDung IN ('A','B','C','D'))
);

-- ============================================================
-- 10. CAU TRA LOI
-- ============================================================
CREATE TABLE CauTraLoi (
    MaCauTraLoi INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_CauTraLoi PRIMARY KEY,
    MaThamGia INT NOT NULL,
    MaCauHoi INT NOT NULL,
    DapAnChon CHAR(1) NULL,
    ThoiGianTraLoi DATETIME2(0) NULL,
    CONSTRAINT FK_CauTraLoi_ThamGia FOREIGN KEY (MaThamGia) REFERENCES ThiSinhTrongPhien(MaThamGia),
    CONSTRAINT FK_CauTraLoi_CauHoi FOREIGN KEY (MaCauHoi) REFERENCES CauHoi(MaCauHoi),
    CONSTRAINT UQ_CauTraLoi UNIQUE (MaThamGia, MaCauHoi),
    CONSTRAINT CK_CauTraLoi_DapAn CHECK (DapAnChon IS NULL OR DapAnChon IN ('A','B','C','D'))
);

-- ============================================================
-- 11. SU KIEN CANH BAO
-- ============================================================
CREATE TABLE SuKienCanhBao (
    MaSuKien BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_SuKienCanhBao PRIMARY KEY,
    MaThamGia INT NOT NULL,
    LoaiSuKien NVARCHAR(60) NOT NULL,
    DoTuongDong DECIMAL(7,5) NULL,
    SoKhuonMat INT NOT NULL CONSTRAINT DF_CanhBao_SoKhuonMat DEFAULT (0),
    ThoiGianBatDau DATETIME2(0) NOT NULL,
    ThoiGianKetThuc DATETIME2(0) NULL,
    ThoiLuongGiay INT NULL,
    DuongDanSnapshot NVARCHAR(500) NULL,
    GhiChu NVARCHAR(500) NULL,
    CONSTRAINT FK_CanhBao_ThamGia FOREIGN KEY (MaThamGia) REFERENCES ThiSinhTrongPhien(MaThamGia),
    CONSTRAINT CK_CanhBao_Loai CHECK (LoaiSuKien IN (N'KHONG_DUNG_NGUOI',N'KHONG_PHAT_HIEN_KHUON_MAT',N'PHAT_HIEN_NHIEU_KHUON_MAT',N'LOI_CAMERA'))
);

-- ============================================================
-- 12. CHI MUC
-- ============================================================
CREATE INDEX IX_SinhVien_MSSV ON SinhVien(MSSV);
CREATE INDEX IX_MayTram_Phong ON MayTram(MaPhong);
CREATE INDEX IX_PhienThi_KyThi_Phong_Ca ON PhienThi(MaKyThi, MaPhong, MaCa);
CREATE INDEX IX_ThiSinh_Phien ON ThiSinhTrongPhien(MaPhienThi);
CREATE INDEX IX_ThiSinh_SinhVien ON ThiSinhTrongPhien(MaSinhVien);
CREATE INDEX IX_ThiSinh_May ON ThiSinhTrongPhien(MaMay);
CREATE INDEX IX_CanhBao_ThamGia_ThoiGian ON SuKienCanhBao(MaThamGia, ThoiGianBatDau);

-- ============================================================
-- 13. DU LIEU CO SO
-- ============================================================
