-- 16. 30 PC CHO MOI PHONG (TONG 90 PC)
;WITH SoMay AS (
    SELECT 1 AS STT
    UNION ALL
    SELECT STT + 1 FROM SoMay WHERE STT < 30
)
INSERT INTO MayTram (MaPhong, MaPC, TenMay, DiaChiIP, TrangThai)
SELECT p.MaPhong,
       N'PC' + RIGHT(N'00' + CONVERT(NVARCHAR(2), s.STT), 2),
       p.TenPhong + N'-PC' + RIGHT(N'00' + CONVERT(NVARCHAR(2), s.STT), 2),
       NULL,
       N'Ngoai tuyen'
FROM PhongThi p CROSS JOIN SoMay s
OPTION (MAXRECURSION 30);

-- 17. TAO 3 PHIEN THI DUOC SU DUNG: P101-Ca1, P102-Ca1, P103-Ca2
INSERT INTO PhienThi (MaKyThi, MaPhong, MaCa, TrangThai)
SELECT k.MaKyThi, p.MaPhong, c.MaCa, N'Chua bat dau'
FROM KyThi k
CROSS JOIN PhongThi p
CROSS JOIN CaThi c
WHERE k.MaKyThiCode=N'EX001'
  AND ((p.TenPhong=N'P101' AND c.TenCa=N'Ca 1')
    OR (p.TenPhong=N'P102' AND c.TenCa=N'Ca 1')
    OR (p.TenPhong=N'P103' AND c.TenCa=N'Ca 2')); 

-- 18. PHAN BO 84 SINH VIEN: 30 + 30 + 24
INSERT INTO ThiSinhTrongPhien (MaPhienThi, MaSinhVien, MaMay, TrangThai)
SELECT ph.MaPhienThi, sv.MaSinhVien, NULL, N'Chua dang nhap'
FROM PhienThi ph
JOIN KyThi k ON k.MaKyThi=ph.MaKyThi
JOIN PhongThi p ON p.MaPhong=ph.MaPhong
JOIN CaThi c ON c.MaCa=ph.MaCa
JOIN SinhVien sv ON 1=1
WHERE k.MaKyThiCode=N'EX001'
  AND ((p.TenPhong=N'P101' AND c.TenCa=N'Ca 1' AND sv.STT BETWEEN 1 AND 30)
    OR (p.TenPhong=N'P102' AND c.TenCa=N'Ca 1' AND sv.STT BETWEEN 31 AND 60)
    OR (p.TenPhong=N'P103' AND c.TenCa=N'Ca 2' AND sv.STT BETWEEN 61 AND 84));

-- 19. BAI THI MINH HOA 5 CAU
INSERT INTO CauHoi (MaKyThi, SoThuTu, NoiDung, LuaChonA, LuaChonB, LuaChonC, LuaChonD, DapAnDung)
SELECT MaKyThi, 1, N'CSDL là viết tắt của cụm từ nào?', N'Cơ sở dữ liệu', N'Công sở dữ liệu', N'Chương trình dữ liệu', N'Cấu trúc dữ liệu', 'A' FROM KyThi WHERE MaKyThiCode=N'EX001';
INSERT INTO CauHoi (MaKyThi, SoThuTu, NoiDung, LuaChonA, LuaChonB, LuaChonC, LuaChonD, DapAnDung)
SELECT MaKyThi, 2, N'SQL được dùng chủ yếu để làm gì?', N'Quản lý và truy vấn cơ sở dữ liệu', N'Vẽ đồ họa', N'Biên tập ảnh', N'Nén video', 'A' FROM KyThi WHERE MaKyThiCode=N'EX001';
INSERT INTO CauHoi (MaKyThi, SoThuTu, NoiDung, LuaChonA, LuaChonB, LuaChonC, LuaChonD, DapAnDung)
SELECT MaKyThi, 3, N'Khóa chính dùng để làm gì?', N'Định danh duy nhất bản ghi', N'Tăng tốc mạng', N'Mã hóa video', N'Tạo tài khoản', 'A' FROM KyThi WHERE MaKyThiCode=N'EX001';
INSERT INTO CauHoi (MaKyThi, SoThuTu, NoiDung, LuaChonA, LuaChonB, LuaChonC, LuaChonD, DapAnDung)
SELECT MaKyThi, 4, N'SELECT trong SQL dùng để làm gì?', N'Truy vấn dữ liệu', N'Xóa bảng', N'Tạo máy trạm', N'Khởi động camera', 'A' FROM KyThi WHERE MaKyThiCode=N'EX001';
INSERT INTO CauHoi (MaKyThi, SoThuTu, NoiDung, LuaChonA, LuaChonB, LuaChonC, LuaChonD, DapAnDung)
SELECT MaKyThi, 5, N'Face Embedding dùng trong hệ thống nhận dạng để làm gì?', N'Biểu diễn đặc trưng khuôn mặt', N'Lưu video', N'Kiểm tra màn hình', N'Đếm số câu hỏi', 'A' FROM KyThi WHERE MaKyThiCode=N'EX001';

-- ============================================================
-- 20. VIEW PHUC VU UNG DUNG
-- ============================================================
EXEC('CREATE VIEW dbo.vw_DanhSachThiSinhTheoPhien AS
SELECT
    pt.MaPhienThi,
    kt.MaKyThiCode,
    kt.TenKyThi,
    p.TenPhong,
    c.TenCa,
    c.GioBatDau,
    c.GioKetThuc,
    sv.MaSinhVien,
    sv.MSSV,
    sv.HoTen,
    t.MaThamGia,
    t.MaMay,
    mt.MaPC,
    t.TrangThai AS TrangThaiThiSinh
FROM dbo.ThiSinhTrongPhien t
JOIN dbo.PhienThi pt ON pt.MaPhienThi=t.MaPhienThi
JOIN dbo.KyThi kt ON kt.MaKyThi=pt.MaKyThi
JOIN dbo.PhongThi p ON p.MaPhong=pt.MaPhong
JOIN dbo.CaThi c ON c.MaCa=pt.MaCa
JOIN dbo.SinhVien sv ON sv.MaSinhVien=t.MaSinhVien
LEFT JOIN dbo.MayTram mt ON mt.MaMay=t.MaMay;');

-- ============================================================
-- 21. KIEM TRA SAU KHI TAO
-- ============================================================
SELECT N'Tài khoản' AS Bang, COUNT(*) AS SoLuong FROM TaiKhoan
UNION ALL SELECT N'Sinh viên', COUNT(*) FROM SinhVien
UNION ALL SELECT N'Phòng thi', COUNT(*) FROM PhongThi
UNION ALL SELECT N'Ca thi', COUNT(*) FROM CaThi
UNION ALL SELECT N'Kỳ thi', COUNT(*) FROM KyThi
UNION ALL SELECT N'Máy trạm', COUNT(*) FROM MayTram
UNION ALL SELECT N'Phiên thi', COUNT(*) FROM PhienThi
UNION ALL SELECT N'Thí sinh trong phiên', COUNT(*) FROM ThiSinhTrongPhien
UNION ALL SELECT N'Câu hỏi', COUNT(*) FROM CauHoi
UNION ALL SELECT N'Câu trả lời', COUNT(*) FROM CauTraLoi
UNION ALL SELECT N'Sự kiện cảnh báo', COUNT(*) FROM SuKienCanhBao;

SELECT MaSinhVien, MSSV, HoTen,
       (SELECT COUNT(*) FROM OPENJSON(sv.FaceEmbedding)) AS SoChieuEmbedding
FROM SinhVien sv
ORDER BY STT;

SELECT p.TenPhong, c.TenCa, COUNT(t.MaThamGia) AS SoThiSinh
FROM PhienThi pt
JOIN PhongThi p ON p.MaPhong=pt.MaPhong
JOIN CaThi c ON c.MaCa=pt.MaCa
LEFT JOIN ThiSinhTrongPhien t ON t.MaPhienThi=pt.MaPhienThi
GROUP BY p.TenPhong, c.TenCa
ORDER BY p.TenPhong, c.TenCa;

COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO

